class Byteo{constructor(){this.container=null,this.robot=null,this.isActive=!1,this.lastMouseMove=Date.now(),this.inactivityThreshold=5e3,this.targetX=0,this.targetY=0,this.currentX=0,this.currentY=0,this.isCarryingCursor=!1,this.animationFrame=null,this.walkingPath=[],this.currentPathIndex=0,this.init()}init(){this.container=document.createElement("div"),this.container.id="byteo-container",this.container.setAttribute("aria-hidden","true"),this.container.innerHTML='\n            <div class="byteo-robot" id="byteo">\n                \x3c!-- Antena --\x3e\n                <div class="byteo-antenna">\n                    <div class="byteo-antenna-ball"></div>\n                </div>\n                \n                \x3c!-- Cabeza --\x3e\n                <div class="byteo-head">\n                    <div class="byteo-eyes">\n                        <div class="byteo-eye left">\n                            <div class="byteo-pupil"></div>\n                        </div>\n                        <div class="byteo-eye right">\n                            <div class="byteo-pupil"></div>\n                        </div>\n                    </div>\n                    <div class="byteo-mouth"></div>\n                </div>\n                \n                \x3c!-- Cuerpo --\x3e\n                <div class="byteo-body">\n                    <div class="byteo-chest"></div>\n                </div>\n                \n                \x3c!-- Brazos --\x3e\n                <div class="byteo-arms">\n                    <div class="byteo-arm left"></div>\n                    <div class="byteo-arm right"></div>\n                </div>\n                \n                \x3c!-- Piernas --\x3e\n                <div class="byteo-legs">\n                    <div class="byteo-leg left"></div>\n                    <div class="byteo-leg right"></div>\n                </div>\n            </div>\n            \n            \x3c!-- Cursor capturado --\x3e\n            <div class="byteo-cursor" id="byteo-cursor">\n                <svg width="20" height="20" viewBox="0 0 20 20">\n                    <path d="M0 0 L0 16 L6 10 L9 16 L11 15 L8 9 L14 9 Z" fill="#0ea5e9"/>\n                </svg>\n            </div>\n            \n            \x3c!-- Mensaje de Byteo --\x3e\n            <div class="byteo-message" id="byteo-message"></div>\n        ',document.body.appendChild(this.container),this.robot=document.getElementById("byteo"),this.currentX=window.innerWidth-100,this.currentY=window.innerHeight-100,this.updatePosition(),this.setupEventListeners(),this.startWatching()}setupEventListeners(){document.addEventListener("mousemove",t=>{this.lastMouseMove=Date.now(),this.isCarryingCursor||(this.targetX=t.clientX,this.targetY=t.clientY,this.lookAtCursor(t.clientX,t.clientY)),this.isCarryingCursor&&this.releaseCursor()}),this.robot.addEventListener("click",()=>{this.sayMessage("¡Hola! Soy Byteo 🤖"),this.dance()}),window.addEventListener("resize",()=>{this.currentX>window.innerWidth-100&&(this.currentX=window.innerWidth-100),this.currentY>window.innerHeight-100&&(this.currentY=window.innerHeight-100),this.updatePosition()})}startWatching(){setInterval(()=>{Date.now()-this.lastMouseMove>this.inactivityThreshold&&!this.isCarryingCursor&&this.grabCursor()},1e3),this.animate()}animate(){if(this.isCarryingCursor){(0===this.walkingPath.length||this.currentPathIndex>=this.walkingPath.length)&&(this.generateWalkingPath(),this.currentPathIndex=0);const t=this.walkingPath[this.currentPathIndex],e=t.x-this.currentX,s=t.y-this.currentY;if(Math.sqrt(e*e+s*s)<5){if(this.currentPathIndex++,this.currentPathIndex<this.walkingPath.length){const t=this.walkingPath[this.currentPathIndex];this.faceDirection(t.x-this.currentX)}}else this.currentX+=.03*e,this.currentY+=.03*s,this.faceDirection(e),this.animateWalking();this.updatePosition(),this.updateCursorPosition()}else{const t=this.targetX-this.currentX,e=this.targetY-this.currentY;Math.sqrt(t*t+e*e)>50?(this.currentX+=.02*t,this.currentY+=.02*e,this.updatePosition(),this.setEmotion("curious")):this.setEmotion("happy")}this.animationFrame=requestAnimationFrame(()=>this.animate())}updatePosition(){const t=this.robot.style.transform.includes("scaleX(-1)")?"scaleX(-1)":"scaleX(1)";this.robot.style.transform=`translate(${this.currentX}px, ${this.currentY}px) ${t}`}updateCursorPosition(){const t=document.getElementById("byteo-cursor");t&&this.isCarryingCursor&&(t.style.transform=`translate(${this.currentX+30}px, ${this.currentY-20}px)`)}lookAtCursor(t,e){const s=document.querySelectorAll(".byteo-pupil"),i=t-this.currentX,n=e-this.currentY,r=Math.atan2(n,i);s.forEach(t=>{const e=3*Math.cos(r),s=3*Math.sin(r);t.style.transform=`translate(${e}px, ${s}px)`})}grabCursor(){this.isCarryingCursor=!0;document.getElementById("byteo-cursor").style.display="block",this.setEmotion("excited"),this.sayMessage("¡Encontré el cursor! 🎯 Vamos a pasear"),document.body.style.cursor="none",this.robot.classList.add("grabbing"),this.generateWalkingPath()}releaseCursor(){this.isCarryingCursor=!1;document.getElementById("byteo-cursor").style.display="none",this.setEmotion("sad"),this.sayMessage("Oh no... se escapó 😢"),document.body.style.cursor="",this.robot.classList.remove("grabbing"),this.robot.classList.remove("walking"),this.walkingPath=[],this.currentPathIndex=0}setEmotion(t){const e=this.robot.querySelector(".byteo-mouth");this.robot.querySelectorAll(".byteo-eye");switch(this.robot.className="byteo-robot "+t,t){case"happy":e.style.borderRadius="0 0 20px 20px",e.style.height="8px";break;case"sad":e.style.borderRadius="20px 20px 0 0",e.style.height="8px";break;case"excited":e.style.borderRadius="50%",e.style.height="15px";break;case"curious":e.style.borderRadius="50%",e.style.height="5px"}}sayMessage(t){const e=document.getElementById("byteo-message");e.textContent=t,e.classList.add("show"),setTimeout(()=>{e.classList.remove("show")},3e3)}dance(){this.robot.classList.add("dancing"),setTimeout(()=>{this.robot.classList.remove("dancing")},2e3)}generateWalkingPath(){this.walkingPath=[];const t=100,e=window.innerWidth-t,s=window.innerHeight-t,i=8+Math.floor(5*Math.random());for(let n=0;n<i;n++)this.walkingPath.push({x:t+Math.random()*(e-t),y:t+Math.random()*(s-t)});const n=[{x:window.innerWidth/2,y:100},{x:100,y:window.innerHeight/2},{x:window.innerWidth-100,y:window.innerHeight/2},{x:window.innerWidth/2,y:window.innerHeight-100}],r=n[Math.floor(Math.random()*n.length)];this.walkingPath.splice(Math.floor(this.walkingPath.length/2),0,r)}faceDirection(t){this.robot.style.transform=t<0?"scaleX(-1)":"scaleX(1)"}animateWalking(){this.robot.classList.add("walking")}}document.addEventListener("DOMContentLoaded",()=>{setTimeout(()=>{window.byteo=new Byteo,console.log("🤖 Byteo está listo para jugar!")},2e3)});